<?php namespace App\Filament\Resources;use App\Filament\Resources\StudentPublicAssignmentResource\Pages;use App\Models\StudentPublicAssignment;use Illuminate\Support\Facades\DB;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;class StudentPublicAssignmentResource extends Resource{protected static ?string $model=StudentPublicAssignment::class;protected static ?string $navigationGroup='Воспитательная работа';protected static ?string $navigationLabel='Общественные поручения';protected static ?string $pluralModelLabel='Общественные поручения';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('student_id')->label('Студент')->options(fn()=>DB::table('students')->where('status','active')->orderBy('last_name')->get()->mapWithKeys(fn($s)=>[$s->id=>trim($s->last_name.' '.$s->first_name)]))->searchable()->required(),Forms\Components\TextInput::make('title')->label('Поручение')->required(),Forms\Components\DatePicker::make('starts_on')->label('Начало'),Forms\Components\DatePicker::make('ends_on')->label('Окончание'),Forms\Components\Select::make('status')->label('Статус')->options(['active'=>'Активно','completed'=>'Выполнено','cancelled'=>'Отменено'])->required(),Forms\Components\Textarea::make('result')->label('Результат')->columnSpan('full')])->columns(2);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('student_id')->label('Студент')->formatStateUsing(fn($s)=>($x=DB::table('students')->where('id',$s)->first())?trim($x->last_name.' '.$x->first_name):'—'),Tables\Columns\TextColumn::make('title')->label('Поручение')->searchable(),Tables\Columns\TextColumn::make('starts_on')->label('Начало')->date('d.m.Y'),Tables\Columns\TextColumn::make('ends_on')->label('Окончание')->date('d.m.Y'),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->actions([Tables\Actions\EditAction::make()->label('Изменить')]);}publ